const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',channels:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',guide:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-12 4h2m4 0h2m-8 3h2"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0l-1 1-1-1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',sources:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="M7 9h10M7 13h6m-6 4h3"/>',settings:'<path d="m9 3-1 3-3 1-2 3 2 3 1 4 4 1 2 3 3-2 4-1 1-4 2-2-2-3-1-4-4-1-3-2Z"/><circle cx="12" cy="12" r="3"/>',remote:'<rect x="7" y="2" width="10" height="20" rx="4"/><circle cx="12" cy="9" r="3"/><path d="M10 17h4m-2-1v2"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m15 5-7 7 7 7"/>',play:'<path d="m8 4 12 8-12 8Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m5 12 4 4L19 6"/>',sync:'<path d="M20 7a9 9 0 0 0-15-2L2 8m0-6v6h6m-4 9a9 9 0 0 0 15 2l3-3m0 6v-6h-6"/>',cast:'<path d="M2 8V5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v14H12M2 13a9 9 0 0 1 9 9M2 18a4 4 0 0 1 4 4"/><circle cx="2" cy="22" r=".5"/>',volume:'<path d="M3 9v6h4l5 4V5L7 9Zm13-1a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',full:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0"/><circle cx="12" cy="20" r=".5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1m0-14-1 1M6 18l-1 1"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',folder:'<path d="M3 7V5a2 2 0 0 1 2-2h5l2 3h7a2 2 0 0 1 2 2v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',link:'<path d="m9 15 6-6m-9 4-2 2a4 4 0 0 0 6 6l3-3m2-7 2-2a4 4 0 0 0-6-6l-3 3"/>',keyboard:'<rect x="2" y="5" width="20" height="14" rx="3"/><path d="M6 9h1m4 0h1m4 0h1M6 13h1m4 0h1m4 0h1M7 16h10"/>',dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>'};
function icon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.info}</svg>`}
const params=new URLSearchParams(location.search);let style=['nocturne','paper','signal'].includes(params.get('style'))?params.get('style'):'nocturne';const explicitDevice=['phone','ipad','desktop','tv'].includes(params.get('device'))?params.get('device'):null;let device=explicitDevice||(innerWidth<600?'phone':innerWidth<1200?'ipad':'desktop');document.documentElement.dataset.style=style;document.documentElement.dataset.device=device;
const channelData=[{id:1,name:'CCTV-9 纪录',mark:'CCTV',num:'9',group:'纪录',title:'向野而生',sub:'森林之境 · 第 3 集',image:'forest',color:'#83b68c',start:'20:00',end:'21:00',next:'蓝色星球',progress:68},{id:2,name:'CCTV-13 新闻',mark:'CCTV',num:'13',group:'新闻',title:'世界这一刻',sub:'晚间新闻 · 纵览全球',image:'city',color:'#d5b78e',start:'20:30',end:'21:00',next:'环球视线',progress:40},{id:3,name:'CCTV-5 体育',mark:'CCTV',num:'5',group:'体育',title:'绿茵之夜',sub:'足球赛事 · 精彩现场',image:'sport',color:'#aac46c',start:'20:00',end:'22:00',next:'体育世界',progress:35},{id:4,name:'CCTV-6 电影',mark:'CCTV',num:'6',group:'电影',title:'山的另一边',sub:'周末影院 · 沿途皆风景',image:'mountain',color:'#99b8cc',start:'19:45',end:'21:30',next:'光影星播客',progress:52},{id:5,name:'东方卫视',mark:'东方',num:'',group:'卫视',title:'城市的温度',sub:'人文纪实 · 城市与人',image:'city',color:'#d69d91',start:'20:15',end:'21:00',next:'今晚面对面',progress:48},{id:6,name:'自然频道',mark:'NAT',num:'+',group:'纪录',title:'深蓝之下',sub:'海洋特辑 · 未知的世界',image:'ocean',color:'#76bbc0',start:'20:00',end:'21:30',next:'海岸线',progress:42},{id:7,name:'湖南卫视',mark:'湖南',num:'',group:'卫视',title:'山野慢生活',sub:'周末特别节目',image:'mountain',color:'#dca06e',start:'20:00',end:'22:00',next:'晚间剧场',progress:34},{id:8,name:'风景频道',mark:'SCENE',num:'',group:'纪录',title:'听，森林',sub:'自然之声 · 4K 慢直播',image:'forest',color:'#98bd97',start:'20:00',end:'23:00',next:'日出时分',progress:23}];
const nav=[['home','home','首页'],['channels','channels','全部频道'],['guide','guide','节目单'],['favorites','heart','我的收藏'],['sources','sources','播放列表']];const validPages=[...nav.map(x=>x[0]),'settings','remote'];let page=validPages.includes(params.get('page'))?params.get('page'):'home';let group='全部',query='',player=null,paused=false,modal=null,searchOpen=false,showLibrary=false,miniPlayer=null,miniPaused=false;
function stored(k,f){try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}}function persist(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}
let favorites=stored('xp-design-favorites',[1,3,6]);if(!Array.isArray(favorites))favorites=[1,3,6];let sources=stored('xp-design-sources',[{name:'我的电视',count:128,url:'https://example.com/playlist.m3u',updated:'今天 19:30'},{name:'自然与旅行',count:24,url:'https://example.com/nature.m3u',updated:'今天 18:00'},{name:'全球新闻',count:36,url:'https://example.com/news.m3u',updated:'昨天 21:00'}]);if(!Array.isArray(sources))sources=[];let settings=stored('xp-design-settings',{epg:true,launch:true,mini:true});let selectedSource=0;let playbackQuality='自动',playbackAudio='国语',sleepTimer=sessionStorage.getItem('xp-sleep-demo')||'关闭',playbackVolume='100%';
const app=document.querySelector('#app');const labels={home:'首页',channels:'全部频道',guide:'节目单',favorites:'我的收藏',sources:'播放列表',remote:'手机遥控',settings:'设置'};const greeting=style==='paper'?'你的频道，井然有序。':style==='signal'?'每个现场，即刻连接。':'此刻，正精彩。';
function logo(){return `<span class="app-logo"><span class="app-monogram">x<span>▶</span></span><b>XPlayer</b></span>`}
function badge(c){return `<span class="channel-logo" style="--logo-color:${c.color}"><b>${c.mark}</b>${c.num?`<em>${c.num}</em>`:''}</span>`}
function navLink(n){return `<button class="nav-item ${page===n[0]?'active':''}" data-page="${n[0]}" aria-current="${page===n[0]?'page':'false'}" aria-label="${n[2]}" title="${n[2]}">${icon(n[1])}<span>${n[2]}</span>${n[0]==='favorites'?`<small>${favorites.length}</small>`:''}</button>`}
function header(){return `<header class="app-header"><div class="mobile-brand">${logo()}</div><div class="breadcrumb">我的空间 <span>/</span> <b>${labels[page]}</b></div><nav class="tv-nav">${nav.slice(0,5).map(navLink).join('')}</nav><div class="header-tools"><label class="search-box ${searchOpen?'is-open':''}">${icon('search')}<input id="channel-search" type="search" placeholder="搜索频道、节目…" aria-label="搜索频道或节目" value="${escapeHTML(query)}"><kbd>/</kbd></label><button class="icon-button search-toggle" data-action="search" aria-label="搜索">${icon('search')}</button><button class="icon-button cast-top" data-page="remote" title="手机遥控">${icon('cast')}</button><button class="local-user" data-page="settings" title="本地设备设置"><span></span>本地空间</button></div></header>`}
function shell(){return `<div class="device-status"><b>20:42</b><span class="dynamic-island"></span><span>${icon('wifi')} ▰</span></div><div class="app-shell"><aside class="sidebar">${logo()}<div class="nav-label">工作空间</div><nav>${nav.map(navLink).join('')}</nav><div class="source-nav"><div class="nav-label">我的播放列表<button class="icon-button" data-action="add-source" aria-label="添加播放列表">${icon('plus')}</button></div>${sources.slice(0,3).map((s,i)=>`<button class="source-link ${i===selectedSource?'chosen':''}" data-source="${i}"><i style="background:${['#95c2a0','#b49bc4','#b1ba88'][i]}"></i><span>${escapeHTML(s.name)}</span><small>${s.count}</small></button>`).join('')}</div><div class="sidebar-bottom"><button class="nav-item ${page==='remote'?'active':''}" data-page="remote">${icon('remote')}<span>手机遥控</span></button><button class="nav-item ${page==='settings'?'active':''}" data-page="settings">${icon('settings')}<span>设置</span></button><div class="sidebar-foot"><span class="online-dot"></span>所有频道，随你而播<span>v2.0</span></div></div></aside><div class="main-shell">${header()}<main class="content" id="content">${body()}</main></div><nav class="bottom-nav">${[nav[0],nav[1],nav[2],nav[3],['settings','settings','我的']].map(navLink).join('')}</nav></div><div class="home-indicator"></div>${player?playerView():miniPlayer?miniView():''}${modal?modalView():''}`}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function intro(title,desc,extra=''){return `<div class="page-heading"><div><span class="section-kicker">${page==='home'?'YOUR DAILY SIGNAL':page==='guide'?'LIVE PROGRAMME GUIDE':page==='sources'?'YOUR CHANNEL COLLECTION':'YOUR PERSONAL SPACE'}</span><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`}
function body(){switch(page){case 'home':return home();case 'channels':return channels();case 'favorites':return channels(true);case 'guide':return guide();case 'sources':return sourcePage();case 'remote':return remotePage();case 'settings':return settingsPage();default:return home()}}
function favoriteButton(c,extra=''){const yes=favorites.includes(c.id);return `<button class="favorite-button ${yes?'is-favorite':''} ${extra}" data-favorite="${c.id}" aria-label="${yes?'取消收藏':'收藏'} ${c.name}" aria-pressed="${yes}">${icon('heart')}</button>`}
function live(){return '<span class="live-tag"><i></i>直播中</span>'}
function hero(c){return `<section class="hero ${style==='paper'?'editorial-hero':''}" aria-label="正在播出 ${c.title}"><div class="hero-image" style="background-image:url('assets/${c.image}.jpg')"></div><div class="hero-shade"></div><div class="hero-top">${live()}<span class="quality-tag">${c.id===1?'4K':'HD'} <span>·</span> 高清直播</span>${favoriteButton(c,'hero-heart')}</div><div class="hero-content"><div class="hero-channel">${badge(c)}<span>${c.name}<i> / </i>${c.group}</span></div><div class="hero-overline">${style==='signal'?'LIVE FROM THE WORLD':'STORIES WORTH YOUR TIME'}</div><h2>${c.title}<span>${style==='signal'?'LIVE.':'Into the wild.'}</span></h2><p>${c.sub} <i>·</i> <span class="hero-description">让视线越过日常，走进更辽阔的世界</span></p><div class="hero-actions"><button class="primary-button" data-play="${c.id}">${icon('play')}立即观看</button><button class="ghost-button" data-page="guide">节目详情 ${icon('arrow')}</button></div></div><div class="hero-bottom"><span><b>${c.start} — ${c.end}</b><i>正在播出 · ${c.title}</i></span><div class="hero-progress"><span style="width:${c.progress}%"></span></div><span class="hero-next">接下来 <b>21:00 · ${c.next}</b></span></div><div class="image-caption">A WINDOW TO THE WORLD / 01</div></section>`}
function home(){const featured=channelData[style==='signal'?2:0];return intro(greeting,'周日，10 月 25 日。留一点时间，给喜欢的频道。',`<div class="heading-status"><i class="online-dot"></i><span>${escapeHTML(sources[selectedSource]?.name||'我的电视')} · 128 个频道</span><button class="icon-button" data-page="sources" aria-label="切换播放列表">${icon('arrow')}</button></div>`)+`<div class="home-feature">${hero(featured)}<aside class="up-next"><div class="subheading"><span>值得停留的此刻</span>${icon('clock')}</div><h3>现在，正在播出</h3>${[channelData[1],channelData[5],channelData[3]].map((c,i)=>`<button class="next-programme" data-play="${c.id}"><span class="next-time">${c.start}<i></i></span><div><span class="next-channel">${c.name}</span><b>${c.title}</b><small>${c.sub}</small></div><span class="next-arrow">${icon('play')}</span></button>`).join('')}<button class="all-guide" data-page="guide">浏览完整节目单 ${icon('arrow')}</button><div class="next-note"><span class="online-dot"></span>跟上直播，也留住片刻。</div></aside></div><section class="channel-section"><div class="section-heading"><h2>${style==='paper'?'常看的，放在眼前。':style==='signal'?'LIVE CHANNELS / 直播频道':'找到你的频道'}<span>LIVE CHANNELS</span></h2><button data-page="channels">全部频道 ${icon('arrow')}</button></div>${filters()}<div class="channel-grid">${filtered(false).slice(0,device==='phone'?4:device==='tv'?4:4).map(card).join('')}</div>${filtered(false).length===0?empty('没有找到这个频道','试试其他分组或名称。'):''}</section><section class="recent-section"><div class="section-heading"><h2>最近看过<span>PICK UP YOUR MOMENT</span></h2><span>所有播放列表</span></div><div class="recent-list">${[channelData[0],channelData[3],channelData[5]].map(c=>`<button class="recent-item" data-play="${c.id}"><img src="assets/${c.image}.jpg" alt="${c.group}频道画面"><span><b>${c.name}</b><small>${c.title} · 上次观看 18 分钟</small></span><span class="recent-play">${icon('play')}</span></button>`).join('')}</div></section><div class="quiet-footer">你的频道，你的节奏。<span>示例内容 · 设计预览</span></div>`}
function filters(){return `<div class="category-bar" role="group" aria-label="频道分组">${['全部','央视','卫视','新闻','体育','电影','纪录'].map((g,i)=>`<button data-group="${g}" class="${group===g?'active':''}" aria-pressed="${group===g}">${g}${g==='全部'?'<span>128</span>':''}</button>`).join('')}<button class="category-more" data-action="group-info" aria-label="更多分组">${icon('dots')}</button></div>`}
function filtered(onlyFav){return channelData.filter(c=>(!onlyFav||favorites.includes(c.id))&&(group==='全部'||(group==='央视'?c.mark==='CCTV':c.group===group))&&(!query||(c.name+c.title+c.group+c.sub).toLowerCase().includes(query.toLowerCase())))}
function card(c){return `<article class="channel-card"><button class="card-picture" data-play="${c.id}" aria-label="观看 ${c.name} ${c.title}"><img src="assets/${c.image}.jpg" alt="${c.title}的示例画面" loading="lazy"><span class="card-live"><i></i>LIVE</span><span class="card-quality">${c.id===1||c.id===8?'4K':'HD'}</span><span class="card-play">${icon('play')}</span><span class="card-picture-title">${c.title}</span></button><div class="card-info"><div class="card-station">${badge(c)}<button data-play="${c.id}">${c.name}</button>${favoriteButton(c)}</div><button class="card-programme" data-play="${c.id}">${c.title}<span>${c.sub.split(' · ')[0]}</span></button><div class="card-progress"><span style="width:${c.progress}%"></span></div><div class="card-time"><span>${c.start} — ${c.end}</span><span>${c.group}</span></div></div></article>`}
function empty(title,desc){return `<div class="empty-state">${icon('search')}<h2>${title}</h2><p>${desc}</p><button class="secondary-button" data-action="reset-filter">查看全部频道</button></div>`}
function channels(onlyFav=false){const arr=filtered(onlyFav);return intro(onlyFav?'喜欢的，随时都在。':'每一个频道，都有好风景。',onlyFav?`已收藏 ${favorites.length} 个频道 · 你的专属频道清单`:'按心情切换分组，或者直接搜索想看的频道。',`<button class="secondary-button" data-page="sources">${icon('sources')}切换播放列表</button>`)+filters()+`<div class="results-heading"><span>${query?`“${escapeHTML(query)}” 的搜索结果`:group+'频道'}</span><span>${arr.length} 个示例频道</span></div><div class="channel-grid full-grid">${arr.map(card).join('')}</div>${!arr.length?empty(onlyFav?'给喜欢的频道一个位置':'暂时没有匹配的频道',onlyFav?'点击频道旁的爱心，就能在这里找到它。':'换个关键词，或查看全部分组。'):''}`}
function guideTime(n){return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function guideBlocks(c,i){const parse=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]);const begin=parse(c.start),end=parse(c.end),base=1200,total=180;return [{title:c.title,from:begin,to:end,current:true},{title:c.next,from:end,to:end+45},{title:['晚间特别节目','深夜放映室','世界的另一面'][i%3],from:end+45,to:end+90}].filter(p=>p.from<base+total&&p.to>base).map(p=>{const left=Math.max(0,p.from-base)/total*100,width=(Math.min(base+total,p.to)-Math.max(base,p.from))/total*100;return `<button class="epg-programme ${p.current?'current':''} ${p.current&&i===0?'featured':''}" style="left:calc(${left}% + 5px);width:calc(${width}% - 9px)" data-programme="${c.id}" data-programme-title="${p.title}" data-programme-start="${guideTime(p.from)}" data-programme-end="${guideTime(p.to)}" data-upcoming="${!p.current}"><span>${guideTime(p.from)} — ${guideTime(p.to)}</span><b>${p.title}</b><small>${p.current?'正在播出':'即将播出'}</small>${p.current?`<i style="width:${c.progress}%"></i>`:''}</button>`}).join('')}
function guide(){const items=channelData.filter(c=>!query||(c.name+c.title).toLowerCase().includes(query.toLowerCase()));return intro('好节目，心中有数。','先看看正在发生什么，再决定把时间交给谁。',`<div class="guide-date"><button data-action="guide-date" aria-label="前一天">${icon('back')}</button><span>10 月 25 日 · 今天</span><button data-action="guide-date" aria-label="后一天">${icon('arrow')}</button></div>`)+`<div class="guide-summary"><span class="live-tag"><i></i>20:42 正在直播</span><span>节目时间与频道信息均为设计示例</span><button class="secondary-button" data-action="now">${icon('clock')}回到现在</button></div><div class="epg-scroll"><div class="epg"><div class="epg-header"><span>频道 / CH.</span><div><b>20:00</b><b>20:45</b><b>21:30</b><b>22:15</b></div></div><div class="epg-now-line"><span>20:42</span></div>${items.map((c,i)=>`<div class="epg-row"><button class="epg-station" data-play="${c.id}">${badge(c)}<span>${c.name}</span></button><div class="epg-programmes">${guideBlocks(c,i)}</div></div>`).join('')}</div></div><p class="page-footnote">节目单由播放列表关联的 XMLTV 数据提供。此预览使用示例数据展示布局。</p>`}
function sourcePage(){return intro('世界很大，从这里连接。','管理你的 M3U / M3U8 播放列表，让熟悉的频道随时就位。',`<button class="primary-button" data-action="add-source">${icon('plus')}添加播放列表</button>`)+`<div class="source-banner"><span class="source-banner-icon">${icon('globe')}</span><div><b>从喜欢的内容，开始你的频道库。</b><p>添加网络链接，或导入本地文件。所有播放列表都留在你的设备上。</p></div><button class="text-link" data-action="preset">浏览推荐源 ${icon('arrow')}</button></div><div class="section-heading"><h2>我的播放列表 <span>${sources.length} COLLECTIONS</span></h2><button data-action="sync">${icon('sync')}全部刷新</button></div><div class="source-grid">${sources.map((s,i)=>`<article class="source-card"><div class="source-card-top"><span class="source-cover cover-${i%3}">${icon(i%2?'globe':'sources')}</span><span class="source-state">${i===selectedSource?'当前使用':'已就绪'}</span></div><h2>${escapeHTML(s.name)}</h2><p>${s.count} 个频道 <i>·</i> M3U 播放列表</p><div class="source-meta">${icon('clock')}更新于 ${escapeHTML(s.updated)}</div><div class="source-card-actions"><button class="secondary-button ${i===selectedSource?'is-current':''}" data-source="${i}">${icon(i===selectedSource?'check':'play')}${i===selectedSource?'正在使用':'切换到此列表'}</button><button class="icon-button" data-edit-source="${i}" aria-label="编辑 ${escapeHTML(s.name)}">${icon('dots')}</button></div></article>`).join('')}<button class="source-add-card" data-action="add-source">${icon('plus')}<b>添加新的播放列表</b><span>网络 URL 或本地文件</span></button></div><div class="sync-callout">${icon('wifi')}<div><b>另一台设备上已经有配置？</b><p>在同一 Wi-Fi 下，选择需要的播放列表、收藏和设置。</p></div><button class="secondary-button" data-action="lan-sync">局域网同步 ${icon('arrow')}</button></div>`}
function remotePage(){return intro('把手机，变成遥控器。','同一个 Wi-Fi，连接大屏。输入、选台，都在手边。')+`<div class="remote-layout"><section class="remote-connection"><div class="connection-art">${icon('cast')}<i></i>${icon('remote')}</div><span class="section-kicker">NEARBY DEVICES</span><h2>发现你的大屏</h2><p>示例设备 · 实际连接需使用 XPlayer 客户端</p><button class="nearby-device" data-action="connect"><span class="nearby-icon">${icon('cast')}</span><span><b>客厅的 XPlayer TV</b><small>192.168.1.108 · 同一局域网</small></span><span class="connection-state">连接 ${icon('arrow')}</span></button><div class="remote-tip">${icon('wifi')}手机与电视需连接同一个 Wi-Fi</div></section><section class="remote-control"><div class="section-heading"><h2>遥控预览</h2><span class="remote-connected">演示模式</span></div><div class="d-pad"><button class="d-up" data-remote="上" aria-label="向上">${icon('back')}</button><button class="d-left" data-remote="左" aria-label="向左">${icon('back')}</button><button class="d-ok" data-remote="确认">OK</button><button class="d-right" data-remote="右" aria-label="向右">${icon('arrow')}</button><button class="d-down" data-remote="下" aria-label="向下">${icon('arrow')}</button></div><div class="remote-bottom"><button class="secondary-button" data-remote="返回">${icon('back')}返回</button><button class="secondary-button" data-remote="播放 / 暂停">${icon('pause')}播放</button><button class="secondary-button" data-remote="主页">${icon('home')}主页</button></div><label class="remote-text">${icon('keyboard')}<input placeholder="在手机上输入频道名称…" aria-label="遥控输入"></label><button class="primary-button remote-send" data-action="send-text">发送到电视 ${icon('arrow')}</button><p class="remote-feedback" id="remote-feedback" aria-live="polite">试试方向键和文字输入</p></section></div>`}
function settingRow(title,desc,key){return `<div class="setting-row"><div><b>${title}</b><p>${desc}</p></div><button class="switch ${settings[key]?'on':''}" role="switch" aria-checked="${!!settings[key]}" aria-label="${title}" data-setting="${key}"><span></span></button></div>`}
function settingsPage(){return intro('按你的习惯来。','一点点偏好，让 XPlayer 成为你的播放器。')+`<div class="settings-layout"><section class="settings-card"><h2>${icon('play')}播放与浏览</h2>${settingRow('启动时刷新频道','保持播放列表中的频道信息最新','launch')}${settingRow('自动更新节目单','同步所关联的 XMLTV 节目数据','epg')}${settingRow('返回时继续播放','浏览其他频道时保留迷你播放器','mini')}<button class="setting-row" data-action="quality"><div><b>默认清晰度</b><p>优先使用播放源提供的最佳画质</p></div><span>自动 ${icon('arrow')}</span></button><button class="setting-row" data-action="sleep"><div><b>睡眠定时</b><p>到时间后，给今天按下暂停</p></div><span>${sleepTimer==='关闭'?'未开启':sleepTimer} ${icon('arrow')}</span></button></section><section class="settings-card"><h2>${icon('sun')}通用</h2><button class="setting-row" data-action="appearance"><div><b>外观</b><p>当前视觉方向</p></div><span>${{nocturne:'静夜',paper:'留白',signal:'信号'}[style]} ${icon('arrow')}</span></button><button class="setting-row" data-action="language"><div><b>语言</b><p>界面显示语言</p></div><span>简体中文 ${icon('arrow')}</span></button><button class="setting-row" data-page="remote"><div><b>手机遥控</b><p>连接同一网络中的电视</p></div><span>${icon('arrow')}</span></button><button class="setting-row" data-action="lan-sync"><div><b>局域网同步</b><p>从另一台设备带来熟悉的配置</p></div><span>${icon('arrow')}</span></button></section><section class="about-card">${logo()}<p>你的频道，你的节奏。</p><span>四端设计探索 · HTML 交互概念稿</span><small>示例节目与画面用于设计演示，未连接真实直播源。</small></section></div>`}
function miniView(){const c=channelData.find(c=>c.id===miniPlayer);return `<aside class="mini-player" aria-label="迷你播放器"><button class="mini-restore" data-play="${c.id}" aria-label="展开 ${c.name}"><img src="assets/${c.image}.jpg" alt=""><span><b>${c.name}</b><small>${c.title} · 演示画面</small></span></button><button class="icon-button" data-action="mini-pause" aria-label="${miniPaused?'继续播放':'暂停播放'}">${icon(miniPaused?'play':'pause')}</button><button class="icon-button" data-action="close-mini" aria-label="关闭迷你播放器">${icon('close')}</button></aside>`}
function playerView(){const c=channelData.find(c=>c.id===player);return `<section class="player-overlay ${showLibrary?'show-library':''}" role="dialog" aria-modal="true" aria-label="播放 ${c.name}"><div class="player-canvas" style="background-image:url('assets/${c.image}.jpg')"><div class="player-gradient"></div><header class="player-header"><button class="icon-button" data-action="close-player" aria-label="返回浏览">${icon('back')}</button><div><b>${c.name}</b><span>${c.title}</span></div><span class="player-demo">交互演示 · 静态画面</span><button class="icon-button" data-action="cast" aria-label="投屏">${icon('cast')}</button></header><div class="player-center"><span class="player-caption">${c.title}<i>${c.sub}</i></span><button class="big-play" data-action="pause" aria-label="${paused?'继续播放':'暂停播放'}">${icon(paused?'play':'pause')}</button></div><div class="player-controls"><div class="player-programme"><div>${live()}<h2>${c.title}</h2><p>${c.sub}</p></div>${favoriteButton(c)}</div><div class="playback-progress"><span style="width:${c.progress}%"></span><i style="left:${c.progress}%"></i></div><div class="player-time"><span>${c.start}</span><span>${c.end} · 接下来 ${c.next}</span></div><div class="control-row"><button class="icon-button" data-action="pause" aria-label="${paused?'继续播放':'暂停播放'}">${icon(paused?'play':'pause')}</button><button class="icon-button volume-control" data-action="volume" aria-label="音量">${icon('volume')}</button><span class="volume-track"></span><button class="live-position" data-action="live-position"><i></i>LIVE</button><div class="control-spacer"></div><button class="control-text" data-action="quality">${playbackQuality==='自动'?(c.id===1?'4K':'HD'):playbackQuality} <span>清晰度</span></button><button class="control-text" data-action="audio">${playbackAudio} <span>音轨</span></button><button class="control-text" data-action="sleep">${icon('clock')}</button><button class="control-text" data-action="library">${icon('channels')}<span>选台</span></button><button class="icon-button fullscreen-control" data-action="fullscreen" aria-label="全屏">${icon('full')}</button></div></div></div><aside class="player-library"><div class="section-heading"><h2>边看，边选</h2><button data-action="library" aria-label="收起频道列表">${icon('close')}</button></div><div class="player-tabs"><b>频道</b><button data-action="player-guide">节目单</button></div>${channelData.slice(0,6).map(cc=>`<button class="player-channel ${cc.id===c.id?'active':''}" data-play="${cc.id}">${badge(cc)}<span><b>${cc.name}</b><small>${cc.title}</small></span>${cc.id===c.id?'<span class="equalizer"><i></i><i></i><i></i></span>':icon('play')}</button>`).join('')}<div class="player-upnext"><span>接下来 · 21:00</span><b>${c.next}</b><p>与喜欢的频道，继续相伴。</p></div></aside></section>`}
function modalView(){let title='',content='';switch(modal.kind){case 'source':{const s=modal.index!==undefined?sources[modal.index]:null;title=s?'编辑播放列表':'添加播放列表';content=`<form id="source-form"><label>列表名称<input name="name" placeholder="例如：我的电视" value="${escapeHTML(s?.name||'')}" required maxlength="40"></label><label>网络地址<input name="url" type="url" placeholder="https://example.com/playlist.m3u" value="${escapeHTML(s?.url||'')}" required></label><p class="form-note">此为交互演示，只在浏览器保存列表信息，不请求直播地址。</p><div class="file-alternative"><span>或者导入本地文件</span><input id="playlist-file" type="file" accept=".m3u,.m3u8" aria-label="选择 M3U 文件"></div><button class="primary-button" type="submit">${icon('plus')}${s?'保存修改':'添加列表'}</button>${s?'<button class="remove-source" type="button" data-action="remove-source">移除此播放列表</button>':''}</form>`;break}case 'programme':{const c=channelData.find(c=>c.id===modal.id);title=modal.title||c.title;content=`<img class="programme-modal-image" src="assets/${c.image}.jpg" alt="${c.title}示例图"><div class="programme-modal-meta">${badge(c)}<b>${c.name}</b>${modal.upcoming?'<span class="source-state">即将播出</span>':live()}</div><p>${c.sub}</p><p>${modal.start||c.start} — ${modal.end||c.end} · 示例节目信息</p>${modal.upcoming?'<p>节目尚未开始，可先观看该频道的当前直播。</p>':''}<button class="primary-button" data-play="${c.id}">${icon('play')}观看当前直播</button>`;break}case 'options':title=modal.title;content=`<div class="option-list">${modal.options.map((o,i)=>`<button data-option="${escapeHTML(o)}">${o}${i===0?icon('check'):''}</button>`).join('')}</div>`;break;case 'sync':title='从局域网设备同步';content=`<div class="sync-device">${icon('wifi')}<h3>书房的 XPlayer</h3><p>192.168.1.102 · 示例设备</p></div><div class="sync-options">${['播放列表','我的收藏','播放器设置'].map(v=>`<label><input type="checkbox" checked> ${v}</label>`).join('')}</div><button class="primary-button" data-action="finish-sync">预览并同步 ${icon('arrow')}</button><p class="form-note">交互演示，不会访问局域网或更改真实设备。</p>`;break;default:title='浏览推荐源';content='<p>选择一个分类，把喜欢的频道带进来。</p><div class="option-list">'+['中国 · 综合频道','全球 · 新闻资讯','世界 · 自然与纪录'].map(n=>`<button data-preset="${n}">${icon('globe')}${n}${icon('plus')}</button>`).join('')+'</div><p class="form-note">演示预置源，仅展示添加流程。</p>'}
return `<div class="modal-backdrop"><section class="app-modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-title"><h2>${title}</h2><button class="icon-button" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div>${content}</section></div>`}
let toastTimer;function toast(s){const t=document.querySelector('#app-toast');t.textContent=s;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),2400)}
function render(keepScroll=false){parent.postMessage({type:'xplayer-page',page:player?'player':page},location.origin==='null'?'*':location.origin);const top=document.querySelector('#content')?.scrollTop||0;app.innerHTML=shell();if(keepScroll)document.querySelector('#content').scrollTop=top;document.querySelector('#channel-search')?.addEventListener('input',e=>{query=e.target.value;if(page!=='channels'&&page!=='favorites'&&page!=='guide')page='channels';const start=e.target.selectionStart;render(true);const input=document.querySelector('#channel-search');input.focus();try{input.setSelectionRange(start,start)}catch{}});document.querySelector('#source-form')?.addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.target);const entry={name:String(data.get('name')).trim(),url:String(data.get('url')).trim(),count:0,updated:'刚刚'};if(!entry.name){toast('请输入列表名称');return}if(modal.index!==undefined)sources[modal.index]={...sources[modal.index],...entry};else sources.push(entry);persist('xp-design-sources',sources);modal=null;page='sources';render();toast('已保存到此浏览器 · 设计演示')});document.querySelector('#playlist-file')?.addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;sources.push({name:file.name.replace(/\.m3u8?$/i,''),url:'本地文件',count:0,updated:'刚刚'});persist('xp-design-sources',sources);modal=null;page='sources';render();toast('已添加文件记录 · 设计演示')});if(modal||player)requestAnimationFrame(()=>{const overlay=document.querySelector('.app-modal')||document.querySelector('.player-overlay');overlay?.querySelector('input,button')?.focus({preventScroll:true})});}
function navigate(p){page=p;query='';group='全部';player=null;modal=null;render();parent.postMessage({type:'xplayer-page',page:player?'player':page},location.origin==='null'?'*':location.origin);const u=new URL(location);u.searchParams.set('page',page);history.replaceState(null,'',u)}
function openPlayer(id){player=id;miniPlayer=null;modal=null;paused=false;showLibrary=device==='ipad'||device==='desktop';render(true)}
function openOptions(title,options){modal={kind:'options',title,options};render(true)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset;if(d.page)return navigate(d.page);if(d.play)return openPlayer(Number(d.play));if(d.favorite){const id=Number(d.favorite),has=favorites.includes(id);favorites=has?favorites.filter(n=>n!==id):[...favorites,id];persist('xp-design-favorites',favorites);const scroll=document.querySelector('#content')?.scrollTop||0;const current=player;render(true);document.querySelector('#content').scrollTop=scroll;if(current)document.querySelector('.player-overlay .favorite-button')?.focus();toast(has?'已取消收藏':'已加入我的收藏');return}if(d.group){group=d.group;render(true);return}if(d.source!==undefined){selectedSource=Number(d.source);navigate('channels');toast(`已切换到「${sources[selectedSource].name}」· 示例频道`);return}if(d.editSource!==undefined){modal={kind:'source',index:Number(d.editSource)};render(true);return}if(d.programme){modal={kind:'programme',id:Number(d.programme),title:d.programmeTitle,start:d.programmeStart,end:d.programmeEnd,upcoming:d.upcoming==='true'};render(true);return}if(d.setting){settings[d.setting]=!settings[d.setting];persist('xp-design-settings',settings);render(true);return}if(d.remote){document.querySelector('#remote-feedback').textContent=`已按下「${d.remote}」· 演示反馈`;return}if(d.option){const choice=d.option;const title=modal?.title;if(title==='选择分组'){group=choice;modal=null;render(true);return}if(title==='外观方向'){style=choice.startsWith('静夜')?'nocturne':choice.startsWith('留白')?'paper':'signal';document.documentElement.dataset.style=style;const u=new URL(location);u.searchParams.set('style',style);history.replaceState(null,'',u);parent.postMessage({type:'xplayer-style',style},location.origin==='null'?'*':location.origin)}if(title==='睡眠定时'){sleepTimer=choice;sessionStorage.setItem('xp-sleep-demo',choice)}if(title==='选择清晰度')playbackQuality=choice.split(' · ')[0];if(title==='选择音轨')playbackAudio=choice.split(' · ')[0];if(title==='播放音量')playbackVolume=choice;modal=null;render(true);toast(title==='界面语言'?'语言入口演示 · 当前交付中文设计稿':`已选择「${choice}」· 本次预览`);return}if(d.preset){sources.push({name:d.preset,count:24,url:'https://example.com/demo.m3u',updated:'刚刚'});persist('xp-design-sources',sources);modal=null;page='sources';render();toast('已添加演示列表');return}switch(d.action){case 'search':searchOpen=!searchOpen;render(true);document.querySelector('#channel-search')?.focus();break;case 'add-source':modal={kind:'source'};render(true);break;case 'remove-source':{const idx=modal.index;sources.splice(idx,1);selectedSource=Math.min(selectedSource,Math.max(0,sources.length-1));persist('xp-design-sources',sources);modal=null;page='sources';render();toast('已从预览中移除此列表');break}case 'close-modal':modal=null;render(true);break;case 'close-player':miniPlayer=settings.mini&&device!=='tv'?player:null;player=null;render(true);break;case 'close-mini':miniPlayer=null;render(true);break;case 'mini-pause':miniPaused=!miniPaused;render(true);break;case 'pause':paused=!paused;document.querySelectorAll('[data-action="pause"]').forEach(el=>{el.innerHTML=icon(paused?'play':'pause');el.setAttribute('aria-label',paused?'继续播放':'暂停播放')});break;case 'library':showLibrary=!showLibrary;document.querySelector('.player-overlay')?.classList.toggle('show-library',showLibrary);break;case 'player-guide':player=null;navigate('guide');break;case 'quality':openOptions('选择清晰度',['自动 · 最佳画质','4K · 2160p','全高清 · 1080p','高清 · 720p']);break;case 'audio':openOptions('选择音轨',['国语 · 默认','English · 立体声']);break;case 'sleep':openOptions('睡眠定时',['关闭','15 分钟后','30 分钟后','60 分钟后','当前节目结束后']);break;case 'volume':openOptions('播放音量',['100%','75%','50%','25%','静音']);break;case 'fullscreen':{const p=document.querySelector('.player-canvas');if(!document.fullscreenElement)p?.requestFullscreen?.().catch(()=>toast('全屏预览已展开'));else document.exitFullscreen?.();break}case 'live-position':toast('已回到当前直播位置 · 演示');break;case 'cast':openOptions('投屏到设备',['客厅电视 · 示例设备','书房显示器 · 示例设备']);break;case 'sync':toast('所有列表已刷新 · 演示反馈');break;case 'preset':modal={kind:'preset'};render(true);break;case 'lan-sync':modal={kind:'sync'};render(true);break;case 'finish-sync':modal=null;render(true);toast('同步预览完成 · 未访问真实设备');break;case 'connect':{const s=document.querySelector('.connection-state');s.innerHTML=icon('check')+'已连接';s.classList.add('connected');document.querySelector('#remote-feedback').textContent='已进入遥控演示，可使用下方方向键';break}case 'send-text':{const input=document.querySelector('.remote-text input');if(!input.value.trim())return toast('先输入想查找的频道');document.querySelector('#remote-feedback').textContent=`发送预览：「${input.value}」`;input.value='';break}case 'now':document.querySelector('.epg-scroll').scrollTo({left:0,behavior:'smooth'});toast('已定位到 20:42 · 示例时间');break;case 'guide-date':toast('当前展示 10 月 25 日的示例节目单');break;case 'reset-filter':query='';group='全部';if(page==='favorites')page='channels';render();break;case 'group-info':openOptions('选择分组',['全部','央视','卫视','新闻','体育','电影','纪录']);break;case 'appearance':openOptions('外观方向',['静夜 · 深松绿','留白 · 暖白蓝','信号 · 石墨琥珀']);break;case 'language':openOptions('界面语言',['简体中文','English']);break}});
document.addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop')){modal=null;render(true)}});
document.addEventListener('keydown',e=>{const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if(e.key==='Escape'){e.preventDefault();if(modal){modal=null;render(true)}else if(player){miniPlayer=settings.mini&&device!=='tv'?player:null;player=null;render(true)}else if(query){query='';render()}else if(page!=='home'){navigate('home')}return}if(e.key==='Tab'&&(modal||player)){const container=document.querySelector(modal?'.app-modal':'.player-overlay');const focusable=[...container.querySelectorAll('button,input,select,[tabindex="0"]')].filter(el=>el.getClientRects().length);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}return}if(typing)return;if(e.key==='/'){e.preventDefault();searchOpen=true;render(true);document.querySelector('#channel-search')?.focus();return}if(e.code==='Space'&&player){e.preventDefault();document.querySelector('[data-action="pause"]')?.click();return}if(device==='tv'&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const root=document.querySelector('.app-modal')||document.querySelector('.player-overlay')||app;const items=[...root.querySelectorAll('button,input')].filter(el=>{const r=el.getBoundingClientRect();return r.width>0&&r.height>0});const active=document.activeElement;if(!items.includes(active)){items[0]?.focus();return}const r=active.getBoundingClientRect(),x=r.x+r.width/2,y=r.y+r.height/2;let best,score=Infinity;for(const el of items){if(el===active)continue;const b=el.getBoundingClientRect(),dx=b.x+b.width/2-x,dy=b.y+b.height/2-y;const primary=e.key==='ArrowRight'?dx:e.key==='ArrowLeft'?-dx:e.key==='ArrowDown'?dy:-dy;if(primary<6)continue;const secondary=Math.abs(e.key==='ArrowRight'||e.key==='ArrowLeft'?dy:dx);const s=primary+secondary*3;if(s<score){best=el;score=s}}best?.focus();best?.scrollIntoView({block:'nearest',inline:'nearest',behavior:'smooth'})}});
if(!explicitDevice)addEventListener('resize',()=>{const next=innerWidth<600?'phone':innerWidth<1200?'ipad':'desktop';if(device!==next){device=next;document.documentElement.dataset.device=device;render(true)}});render();
